        orderCreate(
          input: {
            lineItems: [{ variantId: "gid://graphql-variant/123", quantity: 1 }],
            shippingAddress: { address1: "123 Main St", city: "Anytown", country: "US", zip: "12345" },
            fulfillments: {
              trackingNumbers: ["TRK123456789", "TRK987654321"]
            }
          }
        ) {
          order {
            id
          }
          userErrors {
            field
            message
          }
        }
      }
